fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Ensure all inputs have the same length
    assert_eq!(dst.len(), src.len());
    assert_eq!(dst.len(), mask.len());

    // Zip together the three iterators and select from src or dst based on mask
    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}